# -*- coding: utf-8 -*-
SVGS = ['<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="26" text-anchor="middle" font-size="14.5" font-weight="bold" fill="#0f172a">KELAM İLMİNDE İMAN – BİLGİ İLİŞKİSİ: TASDİK, İKRAR VE MARİFET</text>\n  <rect x="20" y="45" width="210" height="195" rx="10" fill="#dbeafe" stroke="#2563eb" stroke-width="2"/>\n  <text x="125" y="68" text-anchor="middle" font-size="12.5" font-weight="bold" fill="#1e40af">1. Marifet (Bilgi)</text>\n  <text x="32" y="92" font-size="10.5" fill="#1e3a8a">• İman edilecek esasları</text>\n  <text x="40" y="107" font-size="10.5" fill="#1e3a8a">tanıma ve bilme sürecidir.</text>\n  <text x="32" y="128" font-size="10.5" fill="#1e3a8a">• Bilgi imanın <tspan font-weight="bold">ön şartıdır</tspan>;</text>\n  <text x="40" y="143" font-size="10.5" fill="#1e3a8a">ancak tek başına bilgi (marifet)</text>\n  <text x="40" y="158" font-size="10.5" font-weight="bold" fill="#1d4ed8">iman için yeterli değildir.</text>\n  <rect x="32" y="176" width="186" height="50" rx="6" fill="#ffffff" stroke="#60a5fa"/>\n  <text x="125" y="195" text-anchor="middle" font-size="10" fill="#1e3a8a">İblis ve Ehl-i Kitap\'tan bazıları</text>\n  <text x="125" y="210" text-anchor="middle" font-size="10" font-weight="bold" fill="#1e40af">hakikati bildiği hâlde tasdik etmedi!</text>\n  <rect x="245" y="45" width="210" height="195" rx="10" fill="#dcfce7" stroke="#16a34a" stroke-width="2"/>\n  <text x="350" y="68" text-anchor="middle" font-size="12.5" font-weight="bold" fill="#166534">2. Kalp ile Tasdik (Öz)</text>\n  <text x="257" y="92" font-size="10.5" fill="#14532d">• Bilinen inanç esaslarının</text>\n  <text x="265" y="107" font-size="10.5" fill="#14532d">özgür iradeyle gönülden</text>\n  <text x="265" y="122" font-size="10.5" font-weight="bold" fill="#15803d">benimsenip onaylanmasıdır.</text>\n  <text x="257" y="145" font-size="10.5" fill="#14532d">• Mâtürîdî ve Eş\'arîlere göre</text>\n  <text x="265" y="160" font-size="10.5" font-weight="bold" fill="#166534">imanın asıl rüknü tasdiktir.</text>\n  <rect x="257" y="176" width="186" height="50" rx="6" fill="#ffffff" stroke="#4ade80"/>\n  <text x="350" y="195" text-anchor="middle" font-size="10" fill="#14532d">Bilgi zihinsel bir kavrayış,</text>\n  <text x="350" y="210" text-anchor="middle" font-size="10" font-weight="bold" fill="#166534">tasdik ise kalbî teslimiyettir.</text>\n  <rect x="470" y="45" width="210" height="195" rx="10" fill="#fef3c7" stroke="#d97706" stroke-width="2"/>\n  <text x="575" y="68" text-anchor="middle" font-size="12.5" font-weight="bold" fill="#92400e">3. Dil ile İkrar</text>\n  <text x="482" y="92" font-size="10.5" fill="#78350f">• Kalpteki imanın sözle</text>\n  <text x="490" y="107" font-size="10.5" fill="#78350f">dışa vurulmasıdır (Kelime-i</text>\n  <text x="490" y="122" font-size="10.5" fill="#78350f">Tevhid ve Şehadet).</text>\n  <text x="482" y="145" font-size="10.5" fill="#78350f">• Dünyada kişinin Müslüman</text>\n  <text x="490" y="160" font-size="10.5" fill="#78350f">muamelesi görmesi (nikâh,</text>\n  <text x="490" y="175" font-size="10.5" fill="#78350f">cenaze, miras) için şarttır.</text>\n  <rect x="482" y="186" width="186" height="40" rx="6" fill="#ffffff" stroke="#f59e0b"/>\n  <text x="575" y="203" text-anchor="middle" font-size="10" font-weight="bold" fill="#b45309">İkrah (zorlama) altında kalbi</text>\n  <text x="575" y="218" text-anchor="middle" font-size="10" fill="#78350f">imanla dolu olan mümin kalır.</text>\n</svg>', '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="26" text-anchor="middle" font-size="14.5" font-weight="bold" fill="#0f172a">İMANIN DERİNLİĞİ VE DELİLLENDİRİLMESİ: İCMÂLÎ – TAFSÎLÎ, TAKLÎDÎ – TAHKÎKÎ</text>\n  <rect x="20" y="46" width="320" height="194" rx="10" fill="#fae8ff" stroke="#9333ea" stroke-width="2"/>\n  <text x="180" y="68" text-anchor="middle" font-size="12.5" font-weight="bold" fill="#6b21a8">Kapsamına Göre: İcmâlî ve Tafsîlî İman</text>\n  <rect x="34" y="82" width="292" height="68" rx="6" fill="#ffffff" stroke="#c084fc"/>\n  <text x="44" y="100" font-size="11" font-weight="bold" fill="#7e22ce">• İcmâlî (Toplu / Öz) İman:</text>\n  <text x="44" y="116" font-size="10.5" fill="#581c87">İnanılacak esaslara ayrıntıya girmeden toptan inanmak</text>\n  <text x="44" y="132" font-size="10" fill="#581c87">(Kelime-i Tevhid ve Kelime-i Şehadet ile özetlenen ilk basamak).</text>\n  <rect x="34" y="158" width="292" height="68" rx="6" fill="#ffffff" stroke="#c084fc"/>\n  <text x="44" y="176" font-size="11" font-weight="bold" fill="#7e22ce">• Tafsîlî (Ayrıntılı) İman:</text>\n  <text x="44" y="192" font-size="10.5" fill="#581c87">Altı iman esasını (Âmentü) ve Kur\'an-Sünnet hükümlerini</text>\n  <text x="44" y="208" font-size="10" fill="#581c87">tek tek, ayrıntılarıyla bilerek ve öğrenerek tasdik etmektir.</text>\n  <rect x="360" y="46" width="320" height="194" rx="10" fill="#fef2f2" stroke="#dc2626" stroke-width="2"/>\n  <text x="520" y="68" text-anchor="middle" font-size="12.5" font-weight="bold" fill="#991b1b">Deliline Göre: Taklîdî ve Tahkîkî İman</text>\n  <rect x="374" y="82" width="292" height="68" rx="6" fill="#ffffff" stroke="#f87171"/>\n  <text x="384" y="100" font-size="11" font-weight="bold" fill="#b91c1c">• Taklîdî İman:</text>\n  <text x="384" y="116" font-size="10.5" fill="#7f1d1d">Delillere dayanmadan, anne-baba ve sosyal çevreden</text>\n  <text x="384" y="132" font-size="10" fill="#7f1d1d">görüldüğü gibi benimsenen iman (geçerlidir ancak şüpheye açıktır).</text>\n  <rect x="374" y="158" width="292" height="68" rx="6" fill="#ffffff" stroke="#f87171"/>\n  <text x="384" y="176" font-size="11" font-weight="bold" fill="#b91c1c">• Tahkîkî (Delilli / Bilinçli) İman:</text>\n  <text x="384" y="192" font-size="10.5" fill="#7f1d1d">Evrendeki ayetleri tefekkür ederek, aklî ve naklî delillerle</text>\n  <text x="384" y="208" font-size="10" fill="#7f1d1d">kavranan sarsılmaz iman (Kelam ilminin temel hedefi).</text>\n</svg>', '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="26" text-anchor="middle" font-size="14.5" font-weight="bold" fill="#0f172a">İSLAM DÜŞÜNCESİNDE AKIL VE VAHİY İLİŞKİSİ (SAHİH NAKİL – SELİM AKIL)</text>\n  <rect x="25" y="48" width="205" height="190" rx="10" fill="#dbeafe" stroke="#2563eb" stroke-width="2"/>\n  <text x="127" y="70" text-anchor="middle" font-size="12" font-weight="bold" fill="#1e40af">Selim Akıl (Göz Gibidir)</text>\n  <text x="37" y="94" font-size="10.5" fill="#1e3a8a">• Dini sorumluluğun (<tspan font-weight="bold">teklif</tspan>)</text>\n  <text x="45" y="109" font-size="10.5" fill="#1e3a8a">ve muhataplığın temel şartıdır.</text>\n  <text x="37" y="130" font-size="10.5" fill="#1e3a8a">• Vahyi anlar, yorumlar ve</text>\n  <text x="45" y="145" font-size="10.5" fill="#1e3a8a">evrendeki düzenden Yaratıcı\'nın</text>\n  <text x="45" y="160" font-size="10.5" fill="#1e3a8a">varlığına (istidlal) ulaşır.</text>\n  <text x="37" y="182" font-size="10.5" fill="#1e3a8a">• Ancak <tspan font-weight="bold">gayb âlemini</tspan> (ahiret,</text>\n  <text x="45" y="197" font-size="10.5" fill="#1e3a8a">melek) ve ibadet şekillerini</text>\n  <text x="45" y="212" font-size="10.5" font-weight="bold" fill="#1d4ed8">kendi başına bilemez.</text>\n  <rect x="247" y="48" width="205" height="190" rx="10" fill="#fef3c7" stroke="#d97706" stroke-width="2"/>\n  <text x="350" y="70" text-anchor="middle" font-size="12" font-weight="bold" fill="#92400e">Sahih Vahiy (Işık Gibidir)</text>\n  <text x="259" y="94" font-size="10.5" fill="#78350f">• Allah\'ın peygamberler</text>\n  <text x="267" y="109" font-size="10.5" fill="#78350f">aracılığıyla bildirdiği kesin</text>\n  <text x="267" y="124" font-size="10.5" fill="#78350f">ve yanılmaz ilahi bilgidir.</text>\n  <text x="259" y="145" font-size="10.5" fill="#78350f">• Aklın ulaşamadığı gayb</text>\n  <text x="267" y="160" font-size="10.5" fill="#78350f">konularını, ibadet esaslarını</text>\n  <text x="267" y="175" font-size="10.5" fill="#78350f">ve yaratılış gayesini açıklar.</text>\n  <text x="259" y="197" font-size="10.5" font-weight="bold" fill="#b45309">• Aklı hurafelerden koruyarak</text>\n  <text x="267" y="212" font-size="10.5" font-weight="bold" fill="#b45309">hakikate kılavuzluk eder.</text>\n  <rect x="470" y="48" width="205" height="190" rx="10" fill="#dcfce7" stroke="#16a34a" stroke-width="2"/>\n  <text x="572" y="70" text-anchor="middle" font-size="12" font-weight="bold" fill="#166534">Temel Kelam İlkesi</text>\n  <rect x="482" y="86" width="181" height="72" rx="6" fill="#ffffff" stroke="#4ade80"/>\n  <text x="572" y="105" text-anchor="middle" font-size="10.5" font-weight="bold" fill="#15803d">"Sahih nakil ile selim akıl</text>\n  <text x="572" y="121" text-anchor="middle" font-size="10.5" font-weight="bold" fill="#15803d">birbiriyle çelişmez!"</text>\n  <text x="572" y="142" text-anchor="middle" font-size="9.5" fill="#14532d">(Çünkü ikisinin de kaynağı Allah\'tır)</text>\n  <text x="482" y="178" font-size="10" fill="#14532d">• Zahirî (görünürde) çelişki varsa</text>\n  <text x="490" y="193" font-size="10" fill="#14532d">ya rivayet sahih değildir ya da</text>\n  <text x="490" y="208" font-size="10" fill="#14532d">metin aklın ilkeleriyle <tspan font-weight="bold">te\'vil</tspan></text>\n  <text x="490" y="223" font-size="10" fill="#14532d">(yorum) edilerek uzlaştırılır.</text>\n</svg>']

def uygula(v):
    for i, b in enumerate(v.get('bolumler', [])):
        if i < len(SVGS):
            b['gorsel'] = SVGS[i]
